/** Preset avatar library (SVG files in public/avatars, generated by scripts/generate-avatars.mjs). */
export const AVATAR_PRESETS = [
  { id: "soleil", label: "Soleil" },
  { id: "parisien", label: "Parisien" },
  { id: "festival", label: "Festival" },
  { id: "plongee", label: "Plongée" },
  { id: "dj", label: "DJ" },
  { id: "skate", label: "Skate" },
  { id: "montagne", label: "Montagne" },
  { id: "coquin", label: "Coquin" },
  { id: "lecture", label: "Lecture" },
  { id: "fleur", label: "Fleur" },
  { id: "chef", label: "Chef" },
  { id: "explo", label: "Explo" },
  { id: "dodo", label: "Dodo" },
  { id: "star", label: "Star" },
  { id: "pirate", label: "Pirate" },
  { id: "choupi", label: "Choupi" },
] as const;

export const presetUrl = (id: string) => `/avatars/${id}.svg`;

/** True when the value is an image (URL or app path) rather than an emoji/initials. */
export function isImageAvatar(value: string | null | undefined): value is string {
  return !!value && (value.startsWith("/") || value.startsWith("http"));
}

/** Deterministic preset for someone without a photo (e.g. a guest). */
export function defaultPreset(seed: string): string {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return presetUrl(AVATAR_PRESETS[h % AVATAR_PRESETS.length].id);
}

/** The avatar a profile displays: chosen one, else Google photo, else null. */
export function profileAvatar(profile: { custom_avatar_url: string | null; avatar_url: string | null } | null): string | null {
  return profile?.custom_avatar_url ?? profile?.avatar_url ?? null;
}
